const ROLE_N={edit:'Editor',contrib:'Contributor',view:'View only'};
function folderRole(folder){const p=PJ(),a=CL.acl;if(!p)return'contrib';if(p.canEdit)return'edit';if(!a)return'contrib';let f=folder||'';for(;;){const r=(a.folders||{})[f];if(r){if(r[me()])return r[me()];for(const g of CL.groups)if((g.members||[]).includes(me())&&r['g:'+g.id])return r['g:'+g.id];if(r['*'])return r['*']}if(!f)break;f=f.includes('/')?f.slice(0,f.lastIndexOf('/')):''}return a.default||'contrib'}
function watchProject(pid){CL.unsubP.forEach(u=>{try{u()}catch(e){}});CL.unsubP=[];CL.acl=null;CL.issues=[];CL.projIndex={};CL.activity=[];const d=db();if(!d||!pid)return;let initF=false;const prevV={};
 CL.unsubP.push(d.doc(`projects/${pid}/meta/acl`).onSnapshot(x=>{CL.acl=x.exists?x.data():null;refreshProjects()},e=>{}));
 CL.unsubP.push(d.collection(`projects/${pid}/issues`).onSnapshot(snap=>{CL.issues=snap.docs.map(x=>Object.assign({id:x.id},x.data())).sort((a,b)=>b.at-a.at);refreshProjects()},e=>{}));
 CL.unsubP.push(d.collection(`projects/${pid}/index`).onSnapshot(snap=>{CL.projIndex={};snap.docs.forEach(x=>CL.projIndex[x.id]=x.data())},e=>{}));
 CL.unsubP.push(d.collection(`projects/${pid}/activity`).orderBy('at','desc').limit(100).onSnapshot(snap=>{const prev=new Set(CL.activity.map(a=>a.id));CL.activity=snap.docs.map(x=>Object.assign({id:x.id},x.data()));
  if(initF)CL.activity.filter(a=>!prev.has(a.id)&&a.by!==me()).forEach(a=>notify('activity',a.text,{key:'a'+a.id}));refreshProjects()},e=>{}));
 CL.unsubP.push(d.collection(`projects/${pid}/files`).onSnapshot(snap=>{for(const c of snap.docChanges()){const f=c.doc.data(),id=c.doc.id;
   if(initF&&c.type==='modified'&&f.updatedBy!==me()&&(prevV[id]||0)<(f.version||1))notify('activity',`${nameOf(f.updatedBy)} checked in ${f.name} v${f.version}`,{key:'v'+id+f.version});
   if(initF&&c.type==='added'&&f.updatedBy!==me())notify('activity',`${nameOf(f.updatedBy)} uploaded ${f.name}`,{key:'up'+id});prevV[id]=f.version||1}initF=true},e=>{}));
 CL.unsubP.push(d.collection(`projects/${pid}/rfis`).onSnapshot(snap=>{const old=new Map(CL.remote.rfis.map(r=>[r.id,r]));CL.remote.rfis=snap.docs.map(x=>Object.assign({id:x.id},x.data()));
  for(const r of CL.remote.rfis){const o=old.get(r.id);if(o&&o.status!==r.status&&r.by===me()&&r.updatedBy!==me())notify('status',`RFI #${r.no} is ${r.status}`,{key:'rfi'+r.id+r.status});if((!o||o.assignee!==r.assignee)&&r.assignee&&r.assignee.toLowerCase()===myName().toLowerCase()&&r.updatedBy!==me())notify('status',`RFI #${r.no} was assigned to you`,{key:'rfia'+r.id})}
  if(CL.pctx)mergeRemote('rfis');renderField()},e=>{}));
 CL.unsubP.push(d.collection(`projects/${pid}/subs`).onSnapshot(snap=>{CL.remote.subs=snap.docs.map(x=>Object.assign({id:x.id},x.data()));if(CL.pctx)mergeRemote('subs');renderField()},e=>{}))}
async function logActivity(text,extra){const p=PJ(),d=db();if(!p||!d||!p.cur)return;try{await d.doc(`projects/${p.cur}/activity/${nid('a')}`).set(Object.assign({text,by:me(),at:Date.now()},extra||{}))}catch(e){}}
